.immersive-hud{display:none}.results-screen{position:absolute;inset:0;z-index:12;display:none;place-items:center;padding:24px;background:#06110edb;backdrop-filter:blur(8px)}.results-card{width:min(520px,100%);padding:34px;border:1px solid #547052;border-radius:20px;background:linear-gradient(145deg,#10251b,#09160f);box-shadow:0 24px 80px #000b;text-align:center}.results-card h2{margin:8px 0;font-size:clamp(28px,5vw,44px);letter-spacing:-1.5px}.results-subtitle{margin:0 0 24px;color:#a6b8aa}.results-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.results-grid>div{padding:16px 10px;border:1px solid var(--line);border-radius:12px;background:#0a1912}.results-grid strong,.results-grid span{display:block}.results-grid strong{font:700 25px 'DM Mono',monospace;color:var(--lime)}.results-grid span{margin-top:5px;font:500 9px 'DM Mono',monospace;letter-spacing:1.2px;color:var(--muted)}.results-actions{display:flex;gap:10px;margin-top:22px}.results-actions button{flex:1;min-height:46px}.immersive-brand{font:800 13px 'DM Mono',monospace;letter-spacing:1.5px;text-shadow:0 2px 12px #000}.immersive-brand span{display:block;margin-top:5px;color:var(--lime);font-size:10px}.end-session-button{border:1px solid #d5efaa66;border-radius:10px;padding:10px 14px;background:#07140fbf;color:#f2f8f2;font:700 10px 'DM Mono',monospace;letter-spacing:1px}
